          "type": "text",
          "options": [],
          "steps": [
            "Step 1: W = 3 × 10",
            "Step 2: W = 30 N downward."
          ],
          "why": "Weight is mass multiplied by gravitational field strength.",
          "sol": "Step 1: W = 3 × 10\nStep 2: W = 30 N downward.",
          "hint": "Use W = mg.",
          "subject": "physics",
          "chapter": "force_motion_and_mechanics",
          "topic": "The Normal Reaction Force",
          "conceptId": "physics_force_motion_and_mechanics_the_normal_reaction_force",
          "skillId": "physics_force_motion_and_mechanics",
          "subskillId": "physics_force_motion_and_mechanics_q2"
